"use strict";

const express = require("express");
const cors = require("cors");
const { serverErrorHandler } = require("./errorMiddleware");
const { API_PREFIX } = require("../shared/commentDomain");

function createApp({ routers = [] } = {}) {
  const app = express();

  app.use(cors());

  for (const router of routers) {
    app.use(API_PREFIX, router);
  }

  app.use(serverErrorHandler);

  return app;
}

module.exports = { createApp };

"use strict";

const { Sequelize, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function stripFields(instance, fields) {
  const data = { ...instance.get() };

  for (const field of fields) {
    delete data[field];
  }

  return data;
}

class SerializableModel extends Model {
  toJSON() {
    return stripFields(this, this.constructor.hiddenFields ?? []);
  }
}

function createSerializableModel({
  modelName,
  attributes,
  hiddenFields = [],
  associate,
}) {
  class GeneratedModel extends SerializableModel {}

  if (associate) {
    GeneratedModel.associate = associate;
  }

  GeneratedModel.hiddenFields = hiddenFields;
  GeneratedModel.init(attributes, { sequelize, modelName });

  return GeneratedModel;
}

module.exports = {
  sequelize,
  SerializableModel,
  createSerializableModel,
};

